    /**
     * Aggiustamento smoth scroll al variare della media query e dello scroll
     * (per shrink dell'header)
     */
    $(window).on('changed.zf.mediaquery scroll init_smooth_scroll', function(event, newSize, oldSize) {
        Foundation.SmoothScroll.defaults.offset = parseInt($("#page_header").css("height"));
    }).trigger("init_smooth_scroll");



    /**
     * Smooth scroll al load
     */
    if (window.location.hash) {
       Foundation.SmoothScroll.scrollToLoc(window.location.hash);
    }

    // hack for fondation tabs animation 
    $(document).on('change.zf.tabs', function(e) {
        var activeTab =  $($(e.target).find('.is-active a').attr('href'));
        activeTab.css('display', 'none').fadeIn(700);
    });


    /**
     * Animazione elementi pagina
     * attributi disponibili per comportmenti custom
     * data-as-animation: tipo di animazione (v. animate.css)
     * data-as-delay: ritardo di esecuzione
     * data-as-offset: offset per scatenare l'animazione (v. docs waypoint.js)
     * data-as-duration: durata dell'animazione
     *
     * @docs per offset http://imakewebthings.com/waypoints/api/offset-option/
     * @docs per animazioni https://daneden.github.io/animate.css/
     */
    $("[data-animscroll]").each(function() {

        if (!$(this).attr("data-as-animation")) {
            $(this).attr("data-as-animation", "fadeIn");
        }

        var delay = $(this).attr("data-as-delay") ? $(this).attr("data-as-delay") : 0;
        var duration = $(this).attr("data-as-duration") ? $(this).attr("data-as-duration") : 300;
        var options = {
            offset: ($(this).attr("data-as-offset") ? $(this).attr("data-as-offset") : '85%'),
            handler: function(direction) {
                $(this.element).addClass('animated '+$(this.element).attr('data-as-animation'));
            }
        };

        $(this)
            .css("opacity", 0)
            .css("animation-delay", delay)
            .css("animation-duration", duration)
            .waypoint(options);
    });


    /**
     * fine caricamento pagina
     */
    // evento accodato in boot.js
    LoaderManager.eventComplete("site_loading");
    // eliminazione della situazione finale lasciata dall'utente (con layer bianco)
    // se utente torna con il "back" del browser
    /*$(window).on("pageshow", function() {
        LoaderManager.eventComplete("site_loading");
    });*/

});

